-- challenge chal_quiz_jsf_111 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_jsf_111', (SELECT id FROM catalog.course WHERE public_id = 'js-modern-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'js-modern-foundations') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-jsf-1-1' AND is_deleted = false LIMIT 1), 'values-equality-quiz', 'Predict the checkout bugs', 'Two small snippets from the checkout incident: a quantity default that behaves differently for web and mobile clients, and a handful of equality checks around NaN, null and floating-point numbers.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_111'), 'The cart code reads each line''s quantity with:

const qty = line.qty || 1;

The web checkout sends quantities from a form, as strings. The mobile app sends them from JSON, as numbers. A customer sets an item''s quantity to zero to remove it. What is qty on each client?', 'single_choice'::question_type, '|| returns its right-hand side whenever the left-hand side is falsy. The number 0 is falsy, so the mobile app gets 1 and the customer pays for an item they removed. The string "0" is a non-empty string, and every non-empty string is truthy, so the web client keeps "0" (which becomes 0 when multiplied). The same line of code behaves differently because the type of the value is different. ?? only replaces null and undefined, but the real fix is to parse and validate the quantity once, at the edge.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Web: "0" (a non-empty string is truthy). Mobile: 1 (the number 0 is falsy).', true),
        ('Web: 1. Mobile: 1. Zero is falsy in every form.', false),
        ('Web: 1 ("0" is falsy). Mobile: 0 (numbers are never replaced by ||).', false),
        ('Web: "0". Mobile: 0. || only replaces null and undefined.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_111'), 'Which of these expressions evaluate to true in Node 24? (Select all that apply.)', 'multiple_choice'::question_type, 'NaN is the only value that is not equal to itself, so NaN === NaN is false; Object.is(NaN, NaN) uses the SameValue algorithm and returns true. Number.isNaN does not convert its argument: "abc" is a string, not the NaN value, so it returns false (the global isNaN("abc") converts first and returns true). typeof null is "object", a bug kept since the first version of JavaScript for compatibility. 0.1 and 0.2 have no exact binary representation, and their sum is 0.30000000000000004, which is not the same double as 0.3.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_111') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('NaN === NaN', false),
        ('Object.is(NaN, NaN)', true),
        ('Number.isNaN("abc")', false),
        ('typeof null === "object"', true),
        ('0.1 + 0.2 === 0.3', false)
    ) AS o(option_text, is_correct);

