-- challenge chal_quiz_jsf_211 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_jsf_211', (SELECT id FROM catalog.course WHERE public_id = 'js-modern-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'js-modern-foundations') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-jsf-2-1' AND is_deleted = false LIMIT 1), 'closures-capture-variables-quiz', 'Predict what the callbacks see', 'Two loops build an array of callbacks each, one with var and one with let. Predict what they return, then pick the true statements about what a closure captures.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_211'), 'What does this log?

const a = [];
const b = [];
for (var i = 0; i < 3; i++) a.push(() => i);
for (let j = 0; j < 3; j++) b.push(() => j);
console.log(a.map((f) => f()), b.map((f) => f()));', 'single_choice'::question_type, 'var i is one variable for the whole function (or module), and all three arrows close over that same variable. They run after the loop, when i has been incremented to 3, the value that made the condition i < 3 false. let j in a for header gets a new binding for every iteration, initialised with the previous iteration''s value, so each arrow keeps its own j: 0, 1 and 2. A closure stores a reference to the variable, not a copy of its value.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_211') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('[ 0, 1, 2 ] [ 0, 1, 2 ]', false),
        ('[ 3, 3, 3 ] [ 0, 1, 2 ]', true),
        ('[ 2, 2, 2 ] [ 0, 1, 2 ]', false),
        ('[ 3, 3, 3 ] [ 3, 3, 3 ]', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_211'), 'Which statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'A closure keeps a live reference to the variables of the scope where it was created, so it sees every later assignment to them. That is why var in a loop is shared and why a for (let ...) header, which creates a fresh binding per iteration, fixes it. Each call of a factory such as makeCounter() runs its body again and creates new local variables, so every counter has its own private count. Arrow functions do not snapshot values: they close over variables exactly like function expressions. And a const declared inside the loop body is block-scoped, so it is a new binding on every iteration - which is exactly what a later callback needs.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_211') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('A closure keeps a reference to the outer variable itself, so it sees assignments made to that variable after the closure was created.', true),
        ('Each call to a factory like makeCounter() creates a new scope, so two counters it returns never share their count.', true),
        ('Arrow functions capture the values of outer variables at the moment the arrow is created.', false),
        ('Declaring the loop item with const inside the loop body makes no difference, because the callback runs after the loop has finished.', false)
    ) AS o(option_text, is_correct);

