-- challenge chal_quiz_jsf_221 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_jsf_221', (SELECT id FROM catalog.course WHERE public_id = 'js-modern-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'js-modern-foundations') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-jsf-2-2' AND is_deleted = false LIMIT 1), 'es-modules-evaluation-quiz', 'Predict how Node evaluates your modules', 'Three small module graphs: in which order do the bodies run, what does an importer see after an exported variable changes, and what does top-level await really pause?', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_221'), 'The project has "type": "module" in package.json.

// c.js
console.log(''c'');

// a.js
import ''./c.js'';
console.log(''a'');

// b.js
import ''./c.js'';
console.log(''b'');

// main.js
console.log(''main'');
import ''./a.js'';
import ''./b.js'';

What does `node main.js` print?', 'single_choice'::question_type, 'Import declarations are hoisted: Node loads and links the whole graph before any module body runs, no matter where the import lines are written. Evaluation is depth-first and dependencies come first: c.js (first dependency of a.js), then a.js, then b.js, whose dependency c.js has already been evaluated and is not run again, and finally main.js. A module body runs once per process; every later import gets the same cached module.', 1, 3
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_221') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('c, a, b, main', true),
        ('main, c, a, b', false),
        ('c, a, c, b, main', false),
        ('main, c, a, c, b', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_221'), '// counter.js
export let count = 0;
export function inc() { count++; }
export default count;

// main.js
import snapshot, { count, inc } from ''./counter.js'';
inc();

Which statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'A named export of a variable is a live binding: main.js reads the variable inside counter.js, so after inc() it sees 1. `export default count` exports the value of an expression, evaluated once when counter.js ran, so the default import stays 0. Imported bindings are read-only in the importing module: `count = 5` in main.js throws "TypeError: Assignment to constant variable."; only counter.js can change it, for example through inc(). And counter.js is evaluated once: every module that imports it shares the same count.', 2, 3
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_221') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('After inc(), `count` in main.js is 1.', true),
        ('After inc(), `snapshot` (the default import) is still 0.', true),
        ('Writing `count = 5` in main.js sets the counter to 5 for every module.', false),
        ('If report.js also imports counter.js, it gets its own count, starting again at 0.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_221'), '// secrets.js
console.log(''secrets: fetching'');
export const secrets = await fetchSecrets(); // takes about 2 seconds

// metrics.js (imports nothing)
console.log(''metrics: ready'');

// server.js
import { secrets } from ''./secrets.js'';
import ''./metrics.js'';
console.log(''server: listening'');

What is true when you run `node server.js`?', 'single_choice'::question_type, 'Top-level await pauses the evaluation of secrets.js and of every module that depends on it, here server.js, so "server: listening" is printed only after the secrets have arrived, and server.js never sees an unfinished value. It does not block the thread: timers, I/O and modules that do not depend on secrets.js keep running, which is why metrics.js can print first. A CommonJS require() of a module graph that contains top-level await fails with ERR_REQUIRE_ASYNC_MODULE; use import() there instead.', 3, 4
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_221') AND order_index = 3)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('"server: listening" is printed only after fetchSecrets() has resolved; metrics.js, which does not depend on secrets.js, may run during the wait.', true),
        ('The await blocks the whole Node.js process for 2 seconds: no timers, no I/O and no other module run.', false),
        ('server.js runs immediately and sees `secrets` as undefined until the fetch completes.', false),
        ('A CommonJS file can call require(''./secrets.js'') and receives a promise of the module.', false)
    ) AS o(option_text, is_correct);

