-- challenge chal_quiz_jsf_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_jsf_321', (SELECT id FROM catalog.course WHERE public_id = 'js-modern-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'js-modern-foundations') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-jsf-3-2' AND is_deleted = false LIMIT 1), 'dates-time-zones-quiz', 'Which day is it?', 'Predict what toISOString() returns for a Hanoi order, then sort out which Date facts are true: parsing, zero-based months, local getters and daylight saving time.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_321'), 'The report job runs on a server whose time zone is set to Asia/Ho_Chi_Minh (UTC+7). An order is placed in Hanoi at 06:30 on 21 October 2026 and stored as "2026-10-20T23:30:00.000Z".

const day = new Date(order.createdAt).toISOString().slice(0, 10);

What is day?', 'single_choice'::question_type, 'A Date holds one instant, and toISOString() always writes that instant in UTC, whatever the time zone of the machine. 06:30 in Hanoi is 23:30 UTC on the previous day, so the slice is "2026-10-20" on every server, in Hanoi, in Frankfurt or in a container set to UTC. Moving the server to Hanoi changes what toString() and getDate() return, never what toISOString() returns.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_321') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('"2026-10-20", on every server, because toISOString() always uses UTC', true),
        ('"2026-10-21", because the server is in Hanoi and toISOString() uses the server''s time zone', false),
        ('"2026-10-21", because new Date() converts the Z time to local time before formatting', false),
        ('It throws a RangeError, because the string has milliseconds', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_321'), 'Which statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'A date-only ISO string such as "2026-10-21" is parsed as midnight UTC, which is still 20 October (20:00) in New York. A date-time string without an offset, such as "2026-10-21T00:00", is parsed in the machine''s local zone, so its instant depends on where the code runs. The Date constructor counts months from 0, so new Date(2026, 10, 21) is 21 NOVEMBER. getDate() and the other getters without UTC in their name answer in the machine''s local zone (getUTCDate() is the UTC one). Asia/Ho_Chi_Minh is UTC+7 all year today, while America/New_York is UTC-4 in summer and UTC-5 in winter (2026: from 8 March to 1 November), which is why a fixed offset is wrong for New York.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_321') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('new Date("2026-10-21") is midnight UTC, which is still 20 October in New York.', true),
        ('new Date("2026-10-21T00:00") (no Z, no offset) is midnight in the time zone of the machine running the code.', true),
        ('new Date(2026, 10, 21) is 21 October 2026.', false),
        ('date.getDate() returns the day of the month in UTC.', false),
        ('Asia/Ho_Chi_Minh has no daylight saving time today, while America/New_York switches between UTC-4 and UTC-5.', true)
    ) AS o(option_text, is_correct);

