-- challenge chal_fix_jsf_411 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_fix_jsf_411', (SELECT id FROM catalog.course WHERE public_id = 'js-modern-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'js-modern-foundations') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-jsf-4-1' AND is_deleted = false LIMIT 1), 'fix-import-errors-cause', 'Make the import job''s errors explain themselves', 'importOrders() validates a CSV export and saves the rows. Today every failure surfaces as a bare "Error: Import failed" - the invalid row, the line number and the database error are all lost - and when the database is down the job reports "0 rows imported" as a success. Fix it: throw Error objects, give ImportError a proper name and code and keep the original error as its cause, report every invalid row at once in an AggregateError, and close the store on every path. The tests inspect the thrown error and follow its cause chain.', 'open', 'medium'::difficulty_question, 'fix_bug', 20, true, false)
