VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_fix_jsf_411'), 'Valid file: every row is saved and the store is closed', '{"csv":"id,date,amount\nA-1,2026-03-01,19.90\nA-2,2026-03-02,5\nA-3,2026-03-03,120.5"}', '{"outcome":"returned","value":3,"savedRows":3,"closeCalls":1}', 4, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_fix_jsf_411'), 'One invalid date: an ImportError caused by an AggregateError', '{"csv":"id,date,amount\nA-1,2026-03-01,19.90\nA-2,2026-02-30,5\nA-3,2026-03-03,120.5"}', '{"outcome":"threw","error":{"name":"ImportError","message":"Import failed: 1 of 3 rows invalid","code":"IMPORT_INVALID_ROWS","cause":{"name":"AggregateError","message":"Invalid rows","errors":[{"name":"ValidationError","message":"Line 3: invalid date \"2026-02-30\"","code":"INVALID_ROW","line":3}]}},"savedRows":0,"closeCalls":1}', 4, true, false, 2),
