       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_fix_jsf_411'), 'Database down: the original error is kept as the cause', '{"csv":"id,date,amount\nA-1,2026-03-01,19.90\nA-2,2026-03-02,5\nA-3,2026-03-03,120.5","saveFails":{"message":"connection reset","code":"ECONNRESET"}}', '{"outcome":"threw","error":{"name":"ImportError","message":"Import failed: could not save 3 rows","code":"IMPORT_SAVE_FAILED","cause":{"name":"Error","message":"connection reset","code":"ECONNRESET"}},"savedRows":0,"closeCalls":1}', 4, true, false, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_fix_jsf_411'), 'Every row invalid: nothing is saved, both rows are reported', '{"csv":"id,date,amount\nA-9\nA-10,2026-13-01,abc"}', '{"outcome":"threw","error":{"name":"ImportError","message":"Import failed: 2 of 2 rows invalid","code":"IMPORT_INVALID_ROWS","cause":{"name":"AggregateError","message":"Invalid rows","errors":[{"name":"ValidationError","message":"Line 2: expected 3 fields, got 1","code":"INVALID_ROW","line":2},{"name":"ValidationError","message":"Line 3: invalid date \"2026-13-01\"","code":"INVALID_ROW","line":3}]}},"savedRows":0,"closeCalls":1}', 4, false, true, 5);
