WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_421'), 'toCartLine(sku, qty) returns a new object { sku, qty }. This test fails:

import assert from ''node:assert/strict'';

test(''builds a cart line'', () => {
  assert.strictEqual(toCartLine(''A1'', 2), { sku: ''A1'', qty: 2 });
});

The output says: "Values have same structure but are not reference-equal". What is the right fix?', 'single_choice'::question_type, 'strictEqual compares with Object.is. For objects that means "is this the very same object in memory?", and a freshly created object is never the same object as the literal written in the test, even with identical contents. deepStrictEqual compares structure instead: same own keys, same values (compared strictly, so 2 and ''2'' differ), same prototype. Importing plain ''node:assert'' changes nothing here: strictEqual always uses Object.is - only the legacy equal/deepEqual are loose there. assert.ok only checks truthiness, so it would pass for any object at all, including a wrong one.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_421') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Use assert.deepStrictEqual, which compares keys and values (and the prototype) instead of object identity.', true),
        ('Use assert.ok(toCartLine(''A1'', 2)), because the function clearly returns an object.', false),
        ('Import assert from ''node:assert'' instead of ''node:assert/strict'', so strictEqual becomes a loose comparison.', false),
        ('Nothing is wrong with the test: toCartLine must return the same object instance that the test created.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_421'), 'The discount suite contained exactly one check:

const result = applyDiscount(8000, 10);
assert.ok(result);

It was green for months. Which statements about this test are true? (Select all that apply.)', 'multiple_choice'::question_type, 'assert.ok(value) passes for every truthy value. It proves only that applyDiscount(8000, 10) did not throw and did not return a falsy value (0, '''', null, undefined, NaN, false). A price of 800 (the discount instead of the price), 8000 (no discount) or the string ''7200'' all pass, so it cannot tell a correct function from a broken one. Worse, it would FAIL for a correct 100% discount, whose price is 0. A useful assertion compares against an exact expected value: assert.strictEqual(applyDiscount(8000, 10), 7200).', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_jsf_421') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('It passes if applyDiscount returns 800 (the discount amount) instead of 7200 (the price).', true),
        ('It proves that the returned price is a number.', false),
        ('It would fail for a correct applyDiscount(8000, 100), because the right answer, 0, is falsy.', true),
        ('It proves the threshold works, because 8000 is above 5000.', false)
    ) AS o(option_text, is_correct);

